  function business(id){return S.businesses.find(b=>b.id===Number(id));}
  function blockedDays(channelId=S.selectedChannel){if(Array.isArray(S.calendarBlocked))return S.calendarBlocked;return S.calendarBlocked?.[Number(channelId)]||[];}
  function banner(id){return S.banners.find(b=>b.id===Number(id));}
  function statePill(status){const table={pending:['در انتظار بررسی','warn'],approved:['تأیید شده','good'],rejected:['نیازمند اصلاح','bad'],waiting_managers:['در انتظار پاسخ مدیر','warn'],waiting_customer_confirm:['منتظر تأیید شما','warn'],waiting_payment:['در انتظار پرداخت','warn'],paid:['پرداخت‌شده','good'],completed:['انجام‌شده','good'],cancelled:['لغو شده','neutral'],waiting_customer:['منتظر پاسخ مشتری','neutral'],publish:['زمان‌بندی‌شده','good'],scheduled:['زمان‌بندی‌شده','good'],published:['منتشر شده','good'],open:['در انتظار پاسخ','warn'],answered:['پاسخ داده شده','good'],customer_replied:['پاسخ مشتری','warn'],paused:['متوقف','neutral'],active:['فعال','good']};const a=table[status]||[status||'ثبت‌شده','neutral'];return `<span class="pill ${a[1]}">${a[0]}</span>`;}
  function hero({eyebrow,title,desc,iconName='sparkles',actions='',tone=''}){return `<section class="hero ${tone}"><div class="hero-top"><span class="hero-pill">${icon('sparkles',13)} ${eyebrow}</span><span class="hero-state"><i></i> لینک‌بان</span></div><h2>${title}</h2><p>${desc}</p>${actions?`<div class="hero-actions">${actions}</div>`:''}<div class="hero-art"><div class="ring"></div><div class="hero-disc">${icon(iconName,31)}</div><span class="spark a">✦</span><span class="spark b">✧</span></div></section>`;}
  function screenHero({title,desc,iconName='image',tone=''}){return `<section class="screen-hero ${tone}"><div class="screen-icon">${icon(iconName,26)}</div><div class="screen-hero-copy"><span class="eyebrow">فضای کاری شما</span><h2>${title}</h2><p>${desc}</p></div></section>`;}
