  function setPage(p){S.page=p;S.modal=null;save();render();const m=$('.main');if(m)m.scrollTop=0;}
  function renderNav(){const nav=$('#bottomNav');nav.innerHTML=navItems().map(n=>`<button type="button" class="${S.page===n.p?'on':''}" data-action="nav" data-page="${n.p}">${icon(n.i,21)}<span>${n.l}</span></button>`).join('');}
