  function orderWasPublished(o){return !!o&&(['completed','published'].includes(o.status)||!!o.publishedLink);}
  function renderReviewItem(c,r){return `<article class="review-item"><div class="review-person"><span class="review-avatar">${esc((r.user||'کاربر').slice(0,1))}</span><div class="review-person-copy"><strong>${esc(r.user||'کاربر لینک‌بان')}</strong><small>${esc(r.date||'به‌تازگی')} ${r.verified?`<span class="verified-review">· ${icon('check',10)} سفارش تأییدشده</span>`:''}</small></div><span class="review-rating-number">${ratingStars(r.rating,11)} <b>${fa(r.rating)}</b></span></div><p class="review-text">${esc(r.text)}</p><div class="review-actions"><span class="review-source">تجربهٔ استفاده از کانال</span><button data-action="helpful-review" data-id="${r.id}" data-channel="${c.id}">${icon('check',12)} مفید بود <b>${fa(r.helpful||0)}</b></button></div></article>`;}
