    if(type==='ticket'){const ticket={id:S.nextId++,topic:v.topic,title:v.topic,message:v.message,order:v.order,status:'open',user:S.user.name,date:longDate(new Date()),messages:[{from:'customer',text:String(v.message||'').trim(),date:longDate(new Date())}]};S.tickets.unshift(ticket);closeModal();save();render();toast('تیکت نمایشی ثبت شد.');return;}
