    if(type==='tariff'){const targetChannel=channel(Number(v.channelId));const existing=S.tariffDraft.id?tariff(S.tariffDraft.id):null;if(existing){const owner=S.channels.find(ch=>ch.id===existing.channelId);const stored=owner?.tariffs.find(x=>x.id===existing.id);if(stored){stored.name=String(v.name||stored.name).trim();stored.hours=Math.max(1,Number(v.hours)||24);stored.start=v.start||stored.start;stored.price=Math.max(1000,Number(v.price)||stored.price);}S.selectedChannel=existing.channelId;}else{const item={id:S.nextId++,name:String(v.name||'تعرفه جدید').trim(),hours:Math.max(1,Number(v.hours)||24),start:v.start,price:Math.max(1000,Number(v.price)||100000)};targetChannel.tariffs.push(item);S.selectedChannel=targetChannel.id;}closeModal();S.page='managerTariffs';save();render();toast('تعرفه در نمونه ذخیره شد؛ شناسه و ارتباط سفارش‌های قبلی حفظ شد.');return;}
